"""Inspect the workspace: list files and identify SQLite databases."""
import os
import sqlite3

SQLITE_MAGIC = b"SQLite format 3\x00"

print("Current directory:", os.getcwd())
print("--- Files and directories ---")
for entry in sorted(os.listdir(".")):
    path = os.path.join(".", entry)
    print(("DIR " if os.path.isdir(path) else "FILE"), entry)

print("--- SQLite database detection ---")
found = []
for entry in sorted(os.listdir(".")):
    if os.path.isfile(entry):
        with open(entry, "rb") as fh:
            head = fh.read(16)
        if head.startswith(SQLITE_MAGIC) or entry.lower().endswith(
            (".db", ".sqlite", ".sqlite3", ".sql3")
        ):
            found.append(entry)

if not found:
    print("No SQLite database found in the workspace.")
else:
    for name in found:
        print(f"Database candidate: {name}")
        try:
            conn = sqlite3.connect(name)
            cur = conn.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [row[0] for row in cur.fetchall()]
            print(f"  Tables: {tables or '(none)'}")
            conn.close()
        except sqlite3.Error as exc:
            print(f"  Could not read: {exc}")

"""Read-only inspection of the local workspace: list files and report any
SQLite database's tables, DDL, and columns. No writes are performed."""

import os
import sqlite3

CANDIDATE_EXTS = (".db", ".sqlite", ".sqlite3")


def quote_ident(name):
    return '"' + name.replace('"', '""') + '"'


def main():
    here = os.getcwd()
    print("Workspace:", here)
    print("\nFiles in workspace:")
    for entry in sorted(os.listdir(here)):
        print("  ", entry)

    dbs = [
        entry
        for entry in sorted(os.listdir(here))
        if os.path.isfile(os.path.join(here, entry))
        and entry.lower().endswith(CANDIDATE_EXTS)
    ]
    print("\nSQLite candidates found:", dbs)

    for name in dbs:
        path = os.path.join(here, name)
        print("\n=== DB:", name, "===")
        uri = "file:" + path.replace("?", "%3f").replace("#", "%23") + "?mode=ro"
        try:
            with sqlite3.connect(uri, uri=True) as conn:
                cur = conn.cursor()
                objects = cur.execute(
                    "SELECT name, type FROM sqlite_master "
                    "WHERE type IN ('table', 'view') ORDER BY name"
                ).fetchall()
                for obj_name, obj_type in objects:
                    ddl = cur.execute(
                        "SELECT sql FROM sqlite_master WHERE name = ?", (obj_name,)
                    ).fetchone()[0]
                    print(f"\n-- {obj_type}: {obj_name} --")
                    print(ddl if ddl else "(no DDL)")
                    if obj_type == "table":
                        for row in cur.execute(
                            f"PRAGMA table_info({quote_ident(obj_name)})"
                        ):
                            flags = []
                            if row[3]:
                                flags.append("NOT NULL")
                            if row[4] is not None:
                                flags.append("DEFAULT " + repr(row[4]))
                            if row[5]:
                                flags.append("PRIMARY KEY")
                            print(
                                "   col:",
                                row[1],
                                row[2],
                                " ".join(flags) if flags else "",
                            )
        except sqlite3.Error as exc:
            print("  ERROR reading DB:", exc)


if __name__ == "__main__":
    main()

